#endif

typedef int Bool;
#define True 1
#define False 0
typedef int Status;

typedef unsigned long Window;
typedef unsigned long Drawable;
typedef unsigned long Colormap;

typedef struct XshimDisplay {
  Canvas *canvas;
} Display;

typedef struct XshimGC {
  unsigned long foreground;
} *GC;

typedef struct XshimScreen Screen;
typedef struct XshimVisual Visual;

/* background, function and line_width are accepted but ignored: drawing is
 * always GXcopy with 1-pixel lines. */
typedef struct {
  unsigned long foreground;
  unsigned long background;
  int function;
  int line_width;
} XGCValues;

typedef struct {
  unsigned long pixel;
  unsigned short red, green, blue;
  char flags;
  char pad;
} XColor;

typedef struct {
  int x, y;
  int width, height;
  int depth;
  Visual *visual;
  Screen *screen;
  Colormap colormap;
  long your_event_mask;
} XWindowAttributes;

typedef struct {
  short x, y;
} XPoint;

typedef struct {
  short x, y;
  unsigned short width, height;
} XRectangle;

typedef union {
  int type;
  struct {
    int type;
    unsigned int button;
  } xbutton;
} XEvent;

typedef struct {
  char *option;
  char *specifier;
  int argKind;
  void *value;
} XrmOptionDescRec;

enum { XrmoptionNoArg, XrmoptionIsArg, XrmoptionStickyArg, XrmoptionSepArg };

