  struct XshimPixmap *pm = (struct XshimPixmap *)calloc(1, sizeof(*pm));
  if (!pm) return NULL;
  pm->w = w;
  pm->h = h;
  pm->depth = depth;
  pm->stride = (w + 7) / 8;
  if (depth == 1)
    pm->bits = (uint8_t *)malloc((size_t)pm->stride * (size_t)h);
  else
    pm->rgb = (uint16_t *)malloc((size_t)w * (size_t)h * sizeof(uint16_t));
  if (!pm->bits && !pm->rgb) {
    pixmap_free(pm);
    return NULL;
  }
  return pm;
