      const uint16_t colour =
          src->depth == 1
              ? (uint16_t)(bit_at(src, (int)px, (int)py) ? gc->foreground : gc->background)
              : src->rgb[py * src->w + px];
      canvas_point(dpy->canvas, (int)x, (int)y, colour);
    }
  }
}

