  XDrawLine(dpy, d, gc, x, y, x2, y);
  XDrawLine(dpy, d, gc, x2, y, x2, y2);
  XDrawLine(dpy, d, gc, x2, y2, x, y2);
  XDrawLine(dpy, d, gc, x, y2, x, y);
