import re, os
root = "/Users/rod/build/stopwatch-screensaver/"
ported = set(os.listdir(root + "firmware/src/hacks")) | {"maze"}
rows = {}
for line in open(root + "docs/porting-assessment.md"):
    m = re.match(r"\| (\w[\w-]*) \| 2d \| (S|M) \| (.*?) \| (.*?) \| (\d+) \|", line)
    if m: rows[m.group(1)] = (m.group(2), m.group(3)[:70], int(m.group(5)))
out = []
for name, (rate, gaps, lines) in rows.items():
    if name in ported or lines > 1300: continue
    text = open(f"{root}vendor/xscreensaver-6.16/hacks/{name}.c", errors="replace").read()
    libm = len(re.findall(r"\b(sqrt|sin|cos|pow|atan2?|exp|log|tan)\s*\(", text))
    dbl = len(re.findall(r"\bdouble\b", text))
    lic = "jwz" if re.search(r"permission to use, copy, modify, distribute, and sell", text[:3000], re.I) else "OTHER"
    stack = len(re.findall(r"^\s+(?:static\s+)?(?:int|char|unsigned \w+|double|float)\s+\w+\[\s*(\d{3,})\s*\]", text, re.M))
    out.append((libm, dbl, lic, stack, name, rate, lines, gaps))
out.sort(reverse=True)
print("libm  dbl  lic   stackarrs  name  rate lines gaps")
for r in out[:8]: print(r)
print("--- non-jwz licence ---")
for r in [r for r in out if r[2] == "OTHER"][:6]: print(r)
print("--- blaster ---", [r for r in out if r[4] == "blaster"])

